def header(active=''):
    links = [('Herramientas','/calculadoras/placas-solares/','tools'),('Guías','/guias/antes-de-instalar-placas/','guides'),('Método','/metodologia/','method'),('Sobre el proyecto','/sobre-nosotros/','about')]
    nav = ''.join(f'<a href="{url}"{mark}>{label}</a>' for label,url,key in links for mark in [' aria-current="page"' if key==active else ''])
    return f'''<header class="global-header"><div class="header-inner"><a class="site-logo" href="/"><span aria-hidden="true">☼</span><span>Energía Clara</span></a><nav class="global-nav" aria-label="Navegación principal">{nav}<a class="nav-cta" href="/calculadoras/placas-solares/">Empezar a calcular</a></nav></div></header>'''

def footer():
    return '''<footer class="site-footer"><div class="footer-inner"><div><a class="site-logo" href="/"><span aria-hidden="true">☼</span><span>Energía Clara</span></a><p>Herramientas y guías para entender el consumo de tu hogar y comparar inversiones con supuestos visibles.</p></div><div><h3>Explora</h3><a href="/calculadoras/placas-solares/">Placas y batería</a><a href="/calculadoras/aerotermia-gas/">Aerotermia y gas</a><a href="/calculadoras/electrodomesticos/">Electrodomésticos</a><a href="/calculadoras/aislamiento/">Aislamiento</a></div><div><h3>Información</h3><a href="/metodologia/">Metodología y límites</a><a href="/sobre-nosotros/">Sobre el proyecto</a><a href="/privacidad/">Privacidad</a></div></div><div class="footer-bottom">© 2026 Energía Clara · Resultados orientativos. Revisa tus datos antes de contratar o invertir.</div></footer>'''

def doc(title, description, path, body, active='', scripts=(), body_attr=''):
    url = BASE + path
    script_tags = ''.join(f'<script src="/{src}" defer></script>' for src in scripts)
    return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#092f3d"><meta name="description" content="{escape(description, quote=True)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{url}"><title>{escape(title)} | Energía Clara</title>{FAVICON}<link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/site.css">{script_tags}</head><body {body_attr}>{header(active)}{body}{footer()}</body></html>'''

def write(path, content):
    dest = DIST / path.lstrip('/') / 'index.html' if path != '/' else DIST / 'index.html'
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(content)

def section_cards(rows, card_class='feature-card'):
    return ''.join(f'<a class="{card_class}{" featured" if i==0 and card_class=="feature-card" else ""}" href="{url}"><span class="card-index">{i+1:02d} / {escape(kicker)}</span><h3>{escape(title)}</h3><p>{escape(description)}</p><span class="card-link">Abrir {"herramienta" if card_class=="feature-card" else "guía"} ↗</span></a>' for i,(url,title,description,kicker) in enumerate(rows))

tool_cards=[(f'/calculadoras/{slug}/',name,desc,'CALCULADORA') for slug,name,desc,_ in TOOLS]
guide_cards=[(f'/guias/{slug}/',name,desc,'GUÍA PRÁCTICA') for slug,name,desc in GUIDES]
home=f'''<main class="page-shell"><section class="hero"><div class="hero-content"><div class="eyebrow-modern">AHORRO ENERGÉTICO DEL HOGAR</div><h1>Decide con números.<br>Vive con menos gasto.</h1><p>Calcula lo que podrías ahorrar con placas solares, aerotermia, aislamiento y mejores hábitos de consumo. Los supuestos están a la vista para que sepas qué significa cada resultado.</p><div class="hero-actions"><a class="button-link primary" href="/calculadoras/placas-solares/">Calcular ahorro solar ↗</a><a class="button-link ghost" href="#herramientas">Ver herramientas</a></div></div><div class="hero-visual"><img src="/tejado-solar.webp" alt="Tejado de una vivienda con paneles solares" width="1100" height="820"><div class="hero-note"><strong>Tu consumo, tu decisión</strong>Estimaciones editables sin registrarte.</div></div></section><div class="number-strip" aria-label="Qué ofrece la web"><div><strong>6</strong><span>calculadoras prácticas</span></div><div><strong>4</strong><span>guías para decidir mejor</span></div><div><strong>0</strong><span>datos personales necesarios para calcular</span></div></div><section id="herramientas"><div class="section-head"><div><div class="eyebrow-modern">HERRAMIENTAS</div><h2>Empieza por tu pregunta</h2></div><p>Cada calculadora explica qué datos necesita y qué factores deja fuera.</p></div><div class="tool-grid">{section_cards(tool_cards)}</div></section><section><div class="section-head"><div><div class="eyebrow-modern">APRENDE ANTES DE INVERTIR</div><h2>Guías para interpretar las cifras</h2></div><p>Los resultados son más útiles cuando entiendes la factura, el consumo y la oferta que te presentan.</p></div><div class="guide-grid">{section_cards(guide_cards,'guide-card')}</div></section><div class="editorial-cta"><div><h2>Una cifra sola no cuenta toda la historia.</h2><p>Consulta las fórmulas, las fuentes y las limitaciones que usamos.</p></div><a class="button-link primary" href="/metodologia/">Ver metodología ↗</a></div></main>'''
write('/',doc('Ahorro energético del hogar: calculadoras y guías','Compara placas solares, aerotermia, electrodomésticos y aislamiento con calculadoras transparentes y guías en español.','/',home))

OLD_SHELL = TOOL_TEMPLATE.split('  <div class="app-shell">',1)[1].split('  <footer',1)[0]
OLD_SHELL = '<div class="app-shell">' + OLD_SHELL
OLD_SHELL = OLD_SHELL.replace('src="tejado-solar.webp"','src="/tejado-solar.webp"')
OLD_SHELL = OLD_SHELL.replace('href="#solar" aria-label="Energía Clara, ir a calculadora solar"','href="/calculadoras/placas-solares/" aria-label="Energía Clara, ir a calculadora solar"')

TOOL_ARTICLES = {
 'solar': '''<h2>Qué significa esta comparación</h2><p>La producción estimada sale de multiplicar la potencia de la instalación en kWp por la producción anual esperada de cada kWp. Esa segunda cifra depende del municipio, la orientación, la inclinación, las sombras y las pérdidas del sistema. El valor inicial sirve para explorar; antes de comprar conviene sustituirlo por una simulación de tu tejado en <a href="https://re.jrc.ec.europa.eu/pvg_tools/es/" target="_blank" rel="noopener">PVGIS</a> o por el estudio técnico del instalador.</p><h3>Autoconsumo y excedentes</h3><p>La electricidad solar que utilizas en el momento evita comprar esa energía. La que sobra puede compensarse si tu contrato y modalidad lo permiten. En esta herramienta la compensación se limita al coste mensual de la energía comprada; por eso aumentar placas no produce ahorros ilimitados. La batería guarda una parte del excedente para la noche, pero pierde energía en el proceso y añade inversión.</p><h3>Ejemplo de lectura</h3><p>Si una instalación de 3,5 kWp produce 1.450 kWh por kWp y año, su producción estimada es 5.075 kWh anuales. Eso no implica que una casa que consume 4.200 kWh deje de pagar electricidad: importan las horas en las que se produce y consume, los excedentes y el término fijo de la factura.</p><h3>Antes de decidir</h3><ul><li>Suma los kWh de doce facturas y revisa tu precio variable real.</li><li>Comprueba la producción de tu ubicación, orientación y sombras.</li><li>Solicita un desglose de equipos, instalación, legalización y garantías.</li><li>Compara por separado la rentabilidad adicional de la batería.</li></ul><p>Fuente de contexto: <a href="https://www.idae.es/ca/node/10477" target="_blank" rel="noopener">guía de autoconsumo del IDAE</a>. La calculadora es orientativa y no sustituye un estudio técnico o una oferta contractual.</p>''',
 'quotes': '''<h2>Cómo comparar dos presupuestos de forma justa</h2><p>El precio total no basta. Dos propuestas pueden tener distinta potencia, producción, equipos, garantías y alcance de obra. Por eso mostramos el coste por kWp y recalculamos la producción y el ahorro de cada oferta con el mismo consumo, tarifa y porcentaje de consumo diurno. Así se evita que cada instalador presente su cifra bajo hipótesis diferentes.</p><h3>Qué revisar además de la cifra</h3><p>Pregunta por el modelo de paneles e inversor, protecciones, estructura, legalización, monitorización, posible refuerzo eléctrico y tratamiento de sombras. Comprueba si los importes incluyen impuestos y si la garantía cubre equipos, instalación y mano de obra. La potencia nominal tampoco garantiza el rendimiento: una oferta de mayor tamaño puede tener más excedentes de los que tu factura compensa.</p><h3>Una comparación con contexto</h3><p>Una oferta de 6.500 € para 3,5 kWp cuesta aproximadamente 1.857 €/kWp; otra de 7.600 € para 4 kWp, 1.900 €/kWp. La primera es más barata por unidad de potencia, pero la elección depende de cuánto de la producción extra podrás aprovechar. Usa el botón «Analizar con batería» para comprobar si añadir almacenamiento mejora el resultado.</p><p>Consulta también la <a href="https://www.idae.es/ca/node/10477" target="_blank" rel="noopener">guía de autoconsumo del IDAE</a> para entender los pasos y condiciones de una instalación doméstica.</p>''',
 'hours': '''<h2>Por qué importa cuándo consumes</h2><p>Dos hogares pueden gastar los mismos kWh al año y obtener ahorros solares distintos. Si gran parte del consumo ocurre mientras las placas producen, más electricidad se aprovecha directamente. Si el consumo se concentra por la noche, aumentan las compras a la red y el posible interés de desplazar usos o estudiar una batería.</p><h3>Cómo rellenar el perfil</h3><p>Lo más útil es un registro horario de tu distribuidora o comercializadora. Introduce en cada casilla los kWh utilizados entre esa hora y la siguiente. Si solo tienes un día representativo, la herramienta lo multiplica por 365 para dar una referencia anual. No confundas kW, que es potencia instantánea, con kWh, que es energía consumida en el intervalo.</p><h3>Qué representa el porcentaje solar</h3><p>Usamos de 08:00 a 18:00 como una aproximación sencilla para el consumo diurno. No son las horas reales de producción de todos los días: varían con la estación, ubicación y orientación. Tampoco modelamos tarifas por tramos horarios. Si tienes datos de un año completo, usa tus doce facturas para el consumo anual y este perfil solo para estimar el reparto entre día y noche.</p><p>Esta herramienta ayuda a preparar una comparación solar; no sustituye una simulación horaria de generación y demanda.</p>'''
}

for slug,title,description,key in TOOLS[:3]:
    shell=OLD_SHELL
    for k in ('solar','quotes','hours'):
        start=shell.index(f'id="{k}" aria-labelledby=')
        prefix=shell.rfind('<section class="tool-panel',0,start)
        end=shell.find('>',start)
        tag=shell[prefix:end+1]
        tag=tag.replace('class="tool-panel active"','class="tool-panel"').replace(' hidden','')
        if k==key: tag=tag.replace('class="tool-panel"','class="tool-panel active"')
        else: tag=tag[:-1]+' hidden>'
        shell=shell[:prefix]+tag+shell[end+1:]
    for k in ('solar','quotes','hours'):
        nav=f'data-tool="{k}"'
        idx=shell.index(nav)
        prefix=shell.rfind('<button class="nav-item',0,idx)
        end=shell.find('>',idx)
        tag=shell[prefix:end+1].replace('class="nav-item active"','class="nav-item"').replace(' aria-current="page"','')
        if k==key: tag=tag.replace('class="nav-item"','class="nav-item active"').replace('>',' aria-current="page">')
        shell=shell[:prefix]+tag+shell[end+1:]
    start=shell.index(f'id="{key}" aria-labelledby=')
    close=shell.find('      </section>',start)
    shell=shell[:close]+f'<article class="tool-article">{TOOL_ARTICLES[key]}</article>\n'+shell[close:]
    path=f'/calculadoras/{slug}/'
    write(path,doc(title,description,path,shell,'tools',('app.js',)))

EXTRA = {
 'aerotermia-gas': {
  'intro':'Compara el coste de entregar la misma cantidad de calor al hogar con una caldera de gas y una bomba de calor. Ajusta el rendimiento de ambos equipos y los precios de tu contrato.',
  'fields':[('heat','Calor útil anual','kWh/año',12000,100,100000,'Demanda térmica, no consumo comprado.'),('gas','Precio variable del gas','€/kWh',0.10,0,3,'No incluyas el término fijo.'),('efficiency','Rendimiento estacional de la caldera','%',90,40,100,'Ejemplo editable; no es la eficiencia de catálogo.'),('electricity','Precio variable de electricidad','€/kWh',0.22,0,3,'Usa el coste de energía comprada.'),('scop','Rendimiento estacional de la bomba (SCOP)','',3,1,8,'Depende del clima y del sistema de emisión.'),('pump-cost','Precio instalado de aerotermia','€',10000,0,1000000,'Incluye la obra y equipos de la oferta.'),('boiler-cost','Precio instalado de caldera','€',3500,0,1000000,'Alternativa comparable.')],
  'article':'''<h2>Lo que compara esta calculadora</h2><p>La demanda térmica es el calor que la vivienda necesita, no la energía que compra. Para producir ese calor, una caldera consume más gas que el calor entregado porque su rendimiento es inferior al 100 %. La bomba de calor usa electricidad y calor del entorno; su consumo estimado es la demanda útil dividida por el rendimiento estacional o SCOP.</p><p>El SCOP merece especial atención. No es un valor fijo para todas las casas: varía con el equipo, el clima, la temperatura de impulsión, los radiadores o suelo radiante y el uso. El <a href="https://www.idae.es/sites/default/files/documentos/publicaciones_idae/Guias_IDAE_La_Bomba_de_calor_2023_V11.pdf" target="_blank" rel="noopener">IDAE explica cómo cambian las prestaciones</a> con estas condiciones. Pide al instalador una estimación para tu vivienda.</p><h3>Qué queda fuera</h3><p>No sumamos términos fijos, impuestos, mantenimiento, financiación, cambios futuros de precio ni reformas necesarias para adaptar emisores. La recuperación simple compara la diferencia de inversión entre instalar aerotermia y renovar la caldera; no considera el valor del dinero en el tiempo. Si ya tienes una caldera operativa, la inversión relevante puede ser diferente.</p><h3>Antes de invertir</h3><ul><li>Solicita un cálculo de pérdidas térmicas de la vivienda.</li><li>Comprueba la temperatura que necesitan tus radiadores en días fríos.</li><li>Compara ofertas instaladas con el mismo alcance de obra.</li><li>Incluye mantenimiento y posibles cambios de tarifa en tu decisión final.</li></ul>'''
 },
 'electrodomesticos': {
  'intro':'Introduce la potencia y el tiempo de uso de un aparato. Compara su coste anual con un modelo eficiente antes de decidir si merece la pena sustituirlo.',
  'fields':[('watts','Potencia del aparato actual','W',1000,0,20000,'Usa una medición o la ficha del fabricante.'),('hours','Uso al día','horas',1,0,24,'Promedio de los días en que se usa.'),('days','Días de uso al año','días',220,1,365,'Evita contar días sin uso.'),('price','Precio de energía','€/kWh',0.22,0,3,'Precio variable de tu factura.'),('efficient','Potencia del modelo eficiente','W',650,0,20000,'Potencia durante un uso equivalente.'),('purchase','Precio del modelo eficiente','€',450,0,100000,'Se usa para la recuperación simple.')],
  'article':'''<h2>De vatios a euros: el cálculo</h2><p>Un aparato de 1.000 W usado una hora consume 1 kWh. Para estimar un año, dividimos los vatios entre 1.000 y multiplicamos por las horas de uso de cada día y los días al año. Después aplicamos el precio variable por kWh. El mismo proceso se repite para el equipo eficiente y se compara la diferencia.</p><p>Este método funciona bien para aparatos con una potencia relativamente estable, como una resistencia encendida durante intervalos conocidos. Frigoríficos, bombas de calor y electrodomésticos con ciclos variables no consumen a su potencia nominal de forma continua. En esos casos, usa una medición o el consumo de la etiqueta energética. La <a href="https://energy-efficient-products.ec.europa.eu/ecodesign-and-energy-label/understanding-energy-label_en" target="_blank" rel="noopener">Comisión Europea explica qué datos aporta la etiqueta</a>.</p><h3>¿Conviene sustituir un aparato que funciona?</h3><p>La recuperación simple divide el precio del nuevo aparato entre el ahorro anual estimado de electricidad. No incluye reparaciones, vida útil, diferencias de prestaciones ni el valor ambiental de alargar la vida de un equipo. Si el modelo nuevo reemplaza una compra que ya ibas a realizar, compara la diferencia de precio entre los dos candidatos, no el coste total.</p>'''
 },
 'aislamiento': {
  'intro':'Explora cómo puede cambiar la pérdida de calor al mejorar una pared, ventana o cubierta. El resultado es una aproximación física y no una auditoría energética.',
  'fields':[('area','Superficie mejorada','m²',20,0.1,10000,'Área de la pared, ventana o cubierta.'),('before','Transmitancia anterior (U)','W/m²K',2.8,0.01,10,'Cuanto mayor es U, más calor atraviesa.'),('after','Transmitancia posterior (U)','W/m²K',1.3,0.01,10,'Debe ser menor que la anterior para ahorrar.'),('degree','Grados-día de calefacción','K·día/año',1800,0,10000,'Dato climático de referencia de tu zona.'),('system','Rendimiento estacional','',0.9,0.1,10,'0,9 para una caldera; para bomba de calor, usa su SCOP.'),('heat-price','Precio de energía comprada','€/kWh',0.11,0,3,'Gas o electricidad, según tu sistema.'),('investment','Precio de la mejora','€',1500,0,1000000,'Coste instalado estimado.')],
  'article':'''<h2>Qué indica la transmitancia U</h2><p>La transmitancia expresa cuánto calor atraviesa un metro cuadrado cuando existe un grado de diferencia entre interior y exterior. Si mejoras una ventana o una pared, la diferencia entre U anterior y U nueva permite estimar cuánto se reduce la transmisión de calor. Multiplicamos esa diferencia por la superficie y por los grados-día de calefacción, convertidos a horas.</p><h3>Interpretar el resultado con prudencia</h3><p>El cálculo es una aproximación de ingeniería. No modela la ventilación, infiltraciones, puentes térmicos, ganancias solares, hábitos de calefacción, confort ni refrigeración de verano. Tampoco puede decidir la solución constructiva adecuada. Una rehabilitación completa requiere valoración técnica de la envolvente y de posibles problemas de humedad.</p><p>Si introduces un rendimiento de 0,9, el modelo interpreta que necesitas comprar más energía de la que llega como calor útil. Si usas una bomba de calor, el rendimiento estacional puede superar 1, pero debe corresponder a tu instalación. El resultado económico cambia mucho con el clima y el precio de la energía; prueba varios escenarios antes de usarlo como criterio de inversión.</p>'''
 }
}

def extra_calculator(slug,title,description,kind):
    item=EXTRA[slug]
    fields=''.join(f'<label for="{id}">{label} <small>{unit}</small><input id="{id}" type="number" min="{low}" max="{high}" step="any" value="{default}" required><small>{hint}</small></label>' for id,label,unit,default,low,high,hint in item['fields'])
    body=f'''<main class="page-shell"><div class="eyebrow-modern">CALCULADORA / HOGAR</div><div class="article-header"><h1>{title}</h1><p class="lead">{item['intro']}</p></div><div class="calculator-shell"><form class="calculator-form" novalidate>{fields}</form><div class="calculator-results" aria-live="polite"><h2>Resultado estimado</h2><div id="tool-error" class="error-box" hidden></div><div id="tool-output" class="metrics"></div><p id="tool-formula" class="calc-formula"></p></div></div><article class="tool-article">{item['article']}</article><div class="editorial-cta"><div><h2>Compara con tus datos reales.</h2><p>Un presupuesto detallado o una medición mejoran mucho la estimación.</p></div><a class="button-link primary" href="/metodologia/">Ver límites del cálculo ↗</a></div></main>'''
    path=f'/calculadoras/{slug}/'
    write(path,doc(title,description,path,body,'tools',('extra-tools.js',),f'data-calculator="{kind}"'))

for slug,title,description,kind in TOOLS[3:]: extra_calculator(slug,title,description,kind)

GUIDE_CONTENT = {
 'antes-de-instalar-placas': '''<p class="callout">Una oferta solar solo se puede evaluar bien cuando conoces tu consumo, tu tejado y el alcance de la instalación.</p><h2>1. Reúne un año de consumo</h2><p>Suma los kWh de tus últimas doce facturas. Un solo mes puede ser engañoso por la calefacción, refrigeración o cambios de ocupación. Separa el precio variable por kWh del término de potencia, impuestos y otros cargos: una placa reduce sobre todo la energía que compras, pero no elimina necesariamente el resto de la factura.</p><p>Si tu distribuidora ofrece consumo horario, revisa cuándo se concentra. La electricidad que usas mientras las placas producen suele tener más valor económico que la que se vierte a la red. Puedes probar distintos repartos en nuestra <a href="/calculadoras/consumo-horario/">herramienta de consumo horario</a>.</p><h2>2. Estima la producción de tu tejado</h2><p>La potencia de los paneles se expresa en kWp. La energía producida se mide en kWh. Entre ambas hay una relación que depende de radiación local, inclinación, orientación, sombras y pérdidas. <a href="https://re.jrc.ec.europa.eu/pvg_tools/es/" target="_blank" rel="noopener">PVGIS</a>, del Centro Común de Investigación de la Comisión Europea, permite hacer una primera simulación del emplazamiento.</p><p>Pide que cada instalador explique su previsión anual y las pérdidas que aplica. Un número alto de kWh no es automáticamente mejor si proviene de hipótesis optimistas.</p><h2>3. Pide presupuestos comparables</h2><p>Comprueba qué incluye el precio: paneles, inversor, estructura, protecciones, instalación eléctrica, legalización, monitorización, impuestos y garantías. Pregunta por el tratamiento de sombras y por el servicio posterior. Utiliza el <a href="/calculadoras/comparar-presupuestos/">comparador de presupuestos</a> con un mismo consumo y una misma tarifa para las dos ofertas.</p><h2>4. Valora por separado la batería</h2><p>Una batería no crea electricidad; traslada parte de los excedentes a otro momento y tiene pérdidas. Su rentabilidad depende del precio de compra, de lo que podrías cobrar por el excedente y del consumo nocturno. Calcula primero la instalación sin batería y después la mejora adicional que aporta el almacenamiento.</p><h2>5. Comprueba los trámites</h2><p>Las modalidades de autoconsumo, compensación y procedimientos dependen del marco aplicable. La <a href="https://www.idae.es/ca/node/10477" target="_blank" rel="noopener">guía del IDAE</a> explica los pasos generales en España. Verifica con tu instalador y comercializadora las condiciones vigentes para tu caso.</p>''',
 'cuando-compensa-una-bateria': '''<p class="callout">La pregunta útil no es cuánto ahorran las placas con batería, sino cuánto ahorro adicional aporta la batería frente a las mismas placas sin ella.</p><h2>La energía que se puede guardar</h2><p>Una batería doméstica solo aprovecha excedentes solares que de otro modo no consumirías en ese momento. Si tu producción diurna apenas supera el consumo, habrá poco que almacenar. También tiene un límite de capacidad y potencia; comprar una batería grande no garantiza que se cargue todos los días.</p><p>La energía almacenada no se recupera íntegra. Parte se pierde al cargar y descargar. Por eso una comparación razonable resta esas pérdidas y también tiene en cuenta el dinero que habrías recibido por compensar el excedente.</p><h2>El valor del kWh desplazado</h2><p>Supón que una unidad de excedente podría compensarse a un precio bajo y que comprar una unidad por la noche cuesta más. Guardarla puede tener valor, pero hay que descontar las pérdidas. Si tu contrato compensa bien y tus consumos nocturnos son reducidos, el ahorro marginal puede ser pequeño.</p><p>En la <a href="/calculadoras/placas-solares/">comparación de placas y batería</a> mostramos la factura estimada con placas, la factura al añadir batería y la diferencia entre ambas. La recuperación simple de la batería usa solo su coste adicional dividido por esa mejora anual.</p><h2>Qué preguntar al instalador</h2><ul><li>Capacidad útil y capacidad nominal: no son lo mismo.</li><li>Rendimiento de ida y vuelta y garantía de ciclos.</li><li>Potencia de carga y descarga; compatibilidad con el inversor.</li><li>Coste instalado, mantenimiento y sustitución futura.</li><li>Si ofrece respaldo en un corte de suministro y bajo qué condiciones.</li></ul><p>Revisa además escenarios con menos producción o cambios de tarifa. La recuperación simple no equivale a una rentabilidad financiera completa y no incluye degradación ni sustituciones.</p>''',
 'entender-factura-luz': '''<p class="callout">Para valorar un ahorro energético, primero separa qué parte de tu factura puede reducir realmente cada medida.</p><h2>Energía y potencia no son lo mismo</h2><p>La energía se mide en kWh. Es la cantidad de electricidad consumida durante un periodo. La potencia contratada se mide en kW y determina, junto a las condiciones de tu contrato, una parte fija o semirregulada del coste. Una instalación solar puede reducir los kWh comprados de la red, pero no hace desaparecer automáticamente el término de potencia.</p><h2>Encuentra el precio variable</h2><p>Una factura puede incluir precios por periodos horarios, ajustes, impuestos y servicios adicionales. Para nuestras calculadoras, usa un precio medio variable de la energía comprada por kWh. Si tienes varios periodos, puedes estimarlo dividiendo el coste variable de energía entre los kWh del mismo periodo. No dividas el total de la factura entre kWh si quieres aislar el ahorro de autoconsumo: mezclarías conceptos que podrían mantenerse.</p><h2>Consumo anual y patrón horario</h2><p>Para una instalación de placas, suma doce meses de kWh. Para afinar cuánto aprovechas directamente, consulta las curvas horarias que proporcionan muchos distribuidores o comercializadores. Nuestro <a href="/calculadoras/consumo-horario/">perfil de consumo</a> transforma un día representativo en una estimación de reparto durante horas de sol, con límites claramente indicados.</p><h2>Compensación de excedentes</h2><p>Si tienes autoconsumo con compensación, busca el precio al que tu contrato valora la energía vertida. No lo confundas con el precio al que compras energía. Además, revisa el límite de compensación de tu contrato y modalidad. La <a href="https://www.idae.es/ca/node/10477" target="_blank" rel="noopener">guía del IDAE sobre autoconsumo</a> ofrece contexto para España.</p><p>La interpretación exacta de una factura puede variar entre contratos. Si un dato no está claro, solicita a tu comercializadora el desglose antes de introducirlo en una calculadora.</p>''',
 'elegir-aerotermia': '''<p class="callout">Compara sistemas de calefacción sobre el mismo calor entregado a la vivienda, no solo sobre el precio de un kWh de gas frente a uno de electricidad.</p><h2>Empieza por la demanda térmica</h2><p>La demanda útil es el calor que el hogar necesita para mantener el confort. Una caldera quema gas para producirlo, con pérdidas. Una bomba de calor usa electricidad para transportar calor del entorno y puede entregar varias unidades de calor por cada unidad eléctrica. El cociente entre calor entregado y electricidad consumida se expresa como COP en unas condiciones concretas, y como rendimiento estacional cuando se consideran distintas condiciones de funcionamiento.</p><p>El <a href="https://www.idae.es/sites/default/files/documentos/publicaciones_idae/Guias_IDAE_La_Bomba_de_calor_2023_V11.pdf" target="_blank" rel="noopener">IDAE documenta</a> que la prestación cambia con la temperatura exterior y la de impulsión, además del equipo y su dimensionamiento. Por eso conviene pedir una estimación para la vivienda y sus emisores, no trasladar sin más un dato de catálogo.</p><h2>Calcula costes comparables</h2><p>Para la caldera, divide la demanda útil entre su rendimiento estacional y multiplica por el precio variable del gas. Para aerotermia, divide la misma demanda entre el rendimiento estacional de la bomba y multiplica por el precio de electricidad. Nuestra <a href="/calculadoras/aerotermia-gas/">calculadora de aerotermia y gas</a> aplica esas fórmulas y muestra la diferencia anual.</p><h2>No olvides la inversión y la obra</h2><p>Una bomba de calor puede necesitar cambios en radiadores, suelo radiante, espacio exterior, instalación hidráulica o potencia eléctrica. La comparación económica debe incluir ofertas instaladas con el mismo alcance. Si la caldera actual funciona y no planeabas reemplazarla, no tiene sentido tratar su coste hipotético de reposición como un gasto inmediato.</p><p>Prueba varios precios futuros y rendimientos. El ahorro calculado es una referencia para conversar con un profesional, no una garantía de gasto.</p>'''
}

def article_page(title,description,path,article,active='guides',aside=True):
    side='''<aside class="article-aside"><h2>Explora también</h2><a href="/calculadoras/placas-solares/">Calculadora solar</a><a href="/calculadoras/aerotermia-gas/">Aerotermia frente a gas</a><a href="/metodologia/">Cómo calculamos</a></aside>''' if aside else ''
    body=f'''<main class="page-shell"><div class="article-layout"><div><header class="article-header"><div class="eyebrow-modern">{('GUÍA PRÁCTICA' if active=='guides' else 'ENERGÍA CLARA')}</div><h1>{title}</h1><p class="lead">{description}</p></header><article class="article-body">{article}</article></div>{side}</div></main>'''
    write(path,doc(title,description,path,body,active))

for slug,title,description in GUIDES:
    article_page(title,description,f'/guias/{slug}/',GUIDE_CONTENT[slug])

method='''<p>Estas herramientas sirven para explorar decisiones antes de solicitar un estudio técnico o contractual. Los valores iniciales son ejemplos editables, no una predicción para una vivienda concreta. No recibimos los datos que introduces: las operaciones se realizan en tu navegador.</p><h2>Placas solares y batería</h2><p>Producción anual estimada = potencia en kWp × producción en kWh/kWp/año. Distribuimos la producción entre meses con un perfil orientativo y el consumo anual uniformemente entre meses. Primero restamos la energía solar utilizada directamente. Después estimamos excedentes, compensación limitada al coste mensual de la energía comprada y, cuando hay batería, la energía que puede desplazarse hacia la noche descontando pérdidas.</p><p>Este modelo no incorpora simulación horaria real, sombras dinámicas, degradación, mantenimiento, impuestos, término fijo, ayudas, financiación ni cambios de precio. La recuperación simple divide inversión entre ahorro anual y no es una TIR ni una garantía de amortización.</p><h2>Presupuestos y consumo horario</h2><p>Las dos ofertas se calculan con un mismo consumo, reparto diurno y precios para evitar comparaciones basadas en hipótesis distintas. El perfil horario suma 24 valores de kWh, considera como aproximación diurna las horas 08:00–18:00 y multiplica un día por 365. Ni esa franja ni ese día representan todo un año real.</p><h2>Aerotermia y gas</h2><p>Energía de gas comprada = calor útil ÷ rendimiento estacional de caldera. Electricidad de aerotermia = calor útil ÷ rendimiento estacional de bomba. Los costes resultan de multiplicar cada energía por su precio variable. El plazo simple usa la diferencia de inversión instalada, cuando es positiva, dividida por el ahorro anual positivo.</p><h2>Electrodomésticos y aislamiento</h2><p>Para un aparato de potencia aproximadamente constante: kWh/año = W ÷ 1000 × horas/día × días/año. Para aislamiento: reducción de calor transmitido = (U anterior − U nueva) × superficie × grados-día × 24 ÷ 1000. Después ajustamos por el rendimiento del sistema y el precio de energía. No modelamos ciclos variables, ventilación, puentes térmicos ni ganancias solares.</p><h2>Fuentes y revisión</h2><p>Para datos locales de producción, consulta <a href="https://re.jrc.ec.europa.eu/pvg_tools/es/" target="_blank" rel="noopener">PVGIS</a>. Para contexto de autoconsumo y bomba de calor, utilizamos publicaciones del <a href="https://www.idae.es/ca/node/10477" target="_blank" rel="noopener">IDAE</a> y su <a href="https://www.idae.es/sites/default/files/documentos/publicaciones_idae/Guias_IDAE_La_Bomba_de_calor_2023_V11.pdf" target="_blank" rel="noopener">guía de bomba de calor</a>. Para el consumo de productos, consulta la <a href="https://energy-efficient-products.ec.europa.eu/ecodesign-and-energy-label/understanding-energy-label_en" target="_blank" rel="noopener">etiqueta energética europea</a>. Hemos revisado los contenidos en septiembre de 2026; los datos contractuales y normas pueden cambiar. Comprueba la versión vigente de las fuentes.</p>'''
article_page('Cómo calculamos y qué dejamos fuera','Fórmulas, supuestos y límites para interpretar cada resultado.', '/metodologia/',method,'method')

about='''<p>Energía Clara es un proyecto independiente de herramientas para entender el consumo energético doméstico. Nuestro objetivo es que una persona pueda comprobar por sí misma los supuestos detrás de una propuesta de ahorro y llegar mejor preparada a una conversación con instaladores o profesionales.</p><p>Las calculadoras no piden registro ni venden presupuestos. Los valores iniciales son escenarios de ejemplo. Las herramientas muestran fórmulas, límites y enlaces a fuentes públicas. No cobramos por recomendar marcas ni presentamos una opción como ganadora por defecto.</p><h2>Cómo usar el sitio</h2><ol><li>Empieza con tus facturas o mediciones, no con los valores de ejemplo.</li><li>Introduce precios y presupuestos comparables.</li><li>Prueba escenarios pesimistas y optimistas.</li><li>Consulta la <a href="/metodologia/">metodología</a> antes de tomar una decisión económica.</li></ol><p>Este sitio no sustituye una auditoría energética, un proyecto de instalación ni asesoramiento técnico o financiero individual.</p>'''
article_page('Sobre Energía Clara','Una forma más transparente de explorar el ahorro energético en casa.','/sobre-nosotros/',about,'about')

privacy='''<p>Esta página describe el funcionamiento de la versión actual de Energía Clara. Antes de activar publicidad, analítica u otras tecnologías que traten datos, la información se actualizará.</p><h2>Datos de las calculadoras</h2><p>Los números que introduces en las calculadoras se procesan en tu navegador. El código actual no los envía a una base de datos propia y no necesitas crear una cuenta. Al cerrar o recargar la página, los cambios no se conservan de forma deliberada.</p><h2>Servicio de alojamiento</h2><p>Como sucede con cualquier web, el proveedor de alojamiento puede procesar datos técnicos necesarios para entregar la página, como dirección IP, fecha de acceso y solicitudes HTTP. Este documento no afirma que el alojamiento carezca de registros técnicos.</p><h2>Cookies y publicidad</h2><p>El código de esta versión no instala analítica, publicidad ni un sistema propio de cookies de seguimiento. No se muestran anuncios de AdSense. Si se incorpora publicidad, esta política se ampliará con los proveedores, cookies y opciones de consentimiento aplicables antes de activarla.</p><h2>Control de tus datos</h2><p>No hay formularios de envío de datos personales en esta versión. Los valores introducidos pueden borrarse recargando la página. La identidad y el canal de contacto del responsable deberán incorporarse antes de activar servicios que traten datos personales adicionales.</p>'''
article_page('Privacidad','Qué ocurre con los datos que introduces en esta versión de la web.','/privacidad/',privacy,'',False)

paths=['/']+[f'/calculadoras/{slug}/' for slug,_,_,_ in TOOLS]+[f'/guias/{slug}/' for slug,_,_ in GUIDES]+['/metodologia/','/sobre-nosotros/','/privacidad/']
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{BASE}{path}</loc></url>\n' for path in paths)+'</urlset>\n')
(DIST/'robots.txt').write_text(f'User-agent: *\nAllow: /\n\nSitemap: {BASE}/sitemap.xml\n')
